$('undoBtn').onclick=undo;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&pickingColor){cancelColorPick();status('Color selection cancelled.');return}if(!(e.ctrlKey||e.metaKey))return;const tag=e.target?.tagName,type=e.target?.type;if(e.target?.isContentEditable||tag==='TEXTAREA'||tag==='INPUT'&&!['range','color','checkbox'].includes(type))return;if(e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)redo();else undo()}else if(e.key.toLowerCase()==='y'){e.preventDefault();redo()}});
$('exportBtn').onclick=()=>{if(!layers.poster.img)return;const out=document.createElement('canvas');out.width=W;out.height=H;draw(out.getContext('2d'));try{out.toBlob(blob=>{if(blob){download(blob,($('workspaceName').textContent.replace(/[^a-z0-9_-]+/gi,'-')||'poster')+'.png');status('Exported 1000 × 1500 PNG, ready for Plex.')}else status('Export failed. Try uploading your images locally.')},'image/png')}catch(e){status('Export blocked by the image host. Upload the image locally and try again.')}};
canvas.onkeydown=e=>{if(pickingColor||!['poster','service','title'].includes(selectedLayer)||!e.key.startsWith('Arrow'))return;e.preventDefault();if(!e.repeat)checkpoint();const l=layers[selectedLayer],amount=e.shiftKey?2:.25;if(e.key==='ArrowLeft')l.x-=amount;if(e.key==='ArrowRight')l.x+=amount;if(e.key==='ArrowUp')l.y-=amount;if(e.key==='ArrowDown')l.y+=amount;l.x=Math.max(0,Math.min(100,l.x));l.y=Math.max(0,Math.min(100,l.y));draw();properties()};
$('addBrandBtn').onclick=()=>openBrandDialog(false);$('brandForm').onsubmit=async e=>{e.preventDefault();try{const file=$('brandFile').files[0];if(file.size>2e6)throw new Error('Please choose an SVG smaller than 2 MB.');const svg=sanitizeSvg(await file.text());await trimLogo(await loadImage(svgURL(svg)));const b={id:crypto.randomUUID(),name:$('brandName').value.trim(),svg};if(!b.name)throw new Error('Enter a logo name.');brands.push(b);try{persistBrands()}catch(err){brands.pop();throw new Error('Browser storage is full. Remove a custom logo and try again.')}renderLibrary();properties();$('brandForm').reset();$('addBrand').close();if(addFromLayer)await selectBrand(b.id)}catch(err){alert(err.message)}};
$('backupBtn').onclick=()=>download(new Blob([JSON.stringify(brands.filter(b=>b.svg),null,2)],{type:'application/json'}),'posterr-logo-library.json');$('restoreBtn').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data)||data.length>100)throw new Error('Invalid logo library.');const added=data.map(b=>{if(typeof b.name!=='string'||typeof b.svg!=='string')throw new Error('Invalid logo entry.');return {id:crypto.randomUUID(),name:b.name.slice(0,80),svg:sanitizeSvg(b.svg)}});const previous=brands;brands=[...brands,...added];try{persistBrands()}catch(err){brands=previous;throw err}renderLibrary();properties()}catch(err){alert('Could not import logos: '+err.message)}e.target.value=''};
layout();

$('librarySearch').oninput=renderLibrary;
function applyTheme(theme){const light=theme==='light';document.documentElement.dataset.theme=light?'light':'dark';$('themeBtn').textContent=light?'Dark theme':'Light theme';$('themeBtn').setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme');$('themeBtn').setAttribute('aria-pressed',String(light))}
applyTheme(localStorage.getItem('frame-theme')||'dark');$('themeBtn').onclick=()=>{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';applyTheme(theme);localStorage.setItem('frame-theme',theme)};

// Custom color editor: HSV square, hue strip, hex input and poster sampling.
let colorEditor=null;
function hexToHSV(hex){const [r,g,b]=hex.match(/\w\w/g).map(v=>parseInt(v,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d)h=max===r?((g-b)/d)%6:max===g?(b-r)/d+2:(r-g)/d+4;return {h:(h*60+360)%360,s:max?d/max:0,v:max}}
function hsvToHex(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('')}
function openColorPicker(layer,key){cancelColorPick();colorEditor={layer,key,...hexToHSV(layers[layer][key]),recorded:false};paintColorPicker();$('colorPicker').showModal()}
function paintColorPicker(){if(!colorEditor)return;const {h,s,v,layer,key}=colorEditor;$('colorSquare').style.backgroundColor=hsvToHex(h,1,1);$('colorHandle').style.left=s*100+'%';$('colorHandle').style.top=(1-v)*100+'%';$('colorSquare').setAttribute('aria-valuenow',Math.round(s*100));$('colorSquare').setAttribute('aria-valuetext',`Saturation ${Math.round(s*100)}%, brightness ${Math.round(v*100)}%`);$('colorHue').value=h;$('pickerHex').value=layers[layer][key];$('pickerHex').setAttribute('aria-invalid','false');$('pickerSwatch').style.background=layers[layer][key]}
function changeEditorColor(hex){if(!colorEditor.recorded){checkpoint();colorEditor.recorded=true}const {layer,key}=colorEditor;layers[layer][key]=hex;if(layer==='service'&&key==='color')layers.service.recolor=true;draw();properties();paintColorPicker()}
function squareColor(e){if(!colorEditor)return;const r=$('colorSquare').getBoundingClientRect();colorEditor.s=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));colorEditor.v=1-Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))}
$('colorSquare').onpointerdown=e=>{e.preventDefault();$('colorSquare').setPointerCapture(e.pointerId);squareColor(e)};
$('colorSquare').onpointermove=e=>{if(e.buttons===1)squareColor(e)};
$('colorSquare').onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();const delta=(e.key==='ArrowRight'||e.key==='ArrowUp'?1:-1)*.01;if(e.shiftKey||e.key==='ArrowUp'||e.key==='ArrowDown')colorEditor.v=Math.max(0,Math.min(1,colorEditor.v+delta));else colorEditor.s=Math.max(0,Math.min(1,colorEditor.s+delta));changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))};
$('colorHue').oninput=e=>{colorEditor.h=Number(e.target.value);changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))};
$('pickerHex').oninput=e=>{const hex=normalizeHex(e.target.value);e.target.setAttribute('aria-invalid',String(!hex));if(!hex)return;Object.assign(colorEditor,hexToHSV(hex));changeEditorColor(hex)};
$('closeColorPicker').onclick=()=>$('colorPicker').close();
$('pickerEyedropper').onclick=()=>{if(!layers.poster.img){status('Upload or select a poster first.');return}pickingColor={layer:colorEditor.layer,key:colorEditor.key};$('colorPicker').close();canvas.classList.add('color-picking');updateTransformHandle();canvas.focus();status('Click a color on the poster. Press Escape to cancel.')};

function posterRect(){const l=layers.poster;if(!l.img)return null;const scale=Math.max(W/l.img.naturalWidth,H/l.img.naturalHeight)*l.scale/100,w=l.img.naturalWidth*scale,h=l.img.naturalHeight*scale;return {x:W*l.x/100-w/2,y:H*l.y/100-h/2,w,h}}
function selectedRect(){const l=layers[selectedLayer];return l?.img&&l.visible&&['poster','title','service'].includes(selectedLayer)?selectedLayer==='poster'?posterRect():rectFor(l):null}
function updateTransformHandle(){const handle=$('resizeHandle'),r=selectedRect();handle.hidden=!r||!!pickingColor;canvas.classList.toggle('movable',!!r);if(!r)return;const bounds=canvas.getBoundingClientRect(),parent=handle.parentElement?.getBoundingClientRect();if(!parent)return;handle.style.left=(bounds.left-parent.left+Math.min(W,Math.max(0,r.x+r.w))*bounds.width/W)+'px';handle.style.top=(bounds.top-parent.top+Math.min(H,Math.max(0,r.y+r.h))*bounds.height/H)+'px';canvas.classList.toggle('movable',!!r)}
let artworkDrag=null;
function beginArtworkDrag(e,resize=false){if(pickingColor)return;const r=selectedRect();if(!r)return;const bounds=canvas.getBoundingClientRect(),x=(e.clientX-bounds.left)/bounds.width*W,y=(e.clientY-bounds.top)/bounds.height*H;if(!resize&&(x<r.x||x>r.x+r.w||y<r.y||y>r.y+r.h))return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);artworkDrag={layer:selectedLayer,resize,startX:e.clientX,startY:e.clientY,bounds,initial:{...layers[selectedLayer]},rect:r,recorded:false}}
function moveArtwork(e){if(!artworkDrag)return;const d=artworkDrag,dx=(e.clientX-d.startX)/d.bounds.width*W,dy=(e.clientY-d.startY)/d.bounds.height*H;if(!d.recorded){if(Math.abs(dx)+Math.abs(dy)<2)return;checkpoint();d.recorded=true}const l=layers[d.layer];if(d.resize){const ratio=Math.max(.1,1+(dx*d.rect.w+dy*d.rect.h)/(d.rect.w*d.rect.w+d.rect.h*d.rect.h));const key=d.layer==='poster'?'scale':'width';l[key]=Math.max(d.layer==='poster'?10:1,Math.min(d.layer==='poster'?300:100,d.initial[key]*ratio))}else{l.x=Math.max(-100,Math.min(200,d.initial.x+dx/W*100));l.y=Math.max(-100,Math.min(200,d.initial.y+dy/H*100))}draw();properties()}
function endArtworkDrag(){artworkDrag=null}
canvas.onpointerdown=e=>beginArtworkDrag(e);canvas.onpointermove=moveArtwork;canvas.onpointerup=endArtworkDrag;canvas.onpointercancel=endArtworkDrag;
$('resizeHandle').onpointerdown=e=>beginArtworkDrag(e,true);$('resizeHandle').onpointermove=moveArtwork;$('resizeHandle').onpointerup=endArtworkDrag;$('resizeHandle').onpointercancel=endArtworkDrag;
if(typeof ResizeObserver!=='undefined')new ResizeObserver(updateTransformHandle).observe(canvas);

// Editable projects embed each original layer, including custom logos.
function imageForProject(img){if(!img)return null;const surface=document.createElement('canvas');surface.width=img.naturalWidth;surface.height=img.naturalHeight;surface.getContext('2d').drawImage(img,0,0);return surface.toDataURL('image/png')}
function makeProject(){return {format:'posterr-project',version:1,name:$('workspaceName').textContent,mode,media,images,titleLanguage,selectedLayer,neutralOnly:$('neutralOnly').checked,layers:Object.fromEntries(Object.entries(layers).map(([id,l])=>{const {img,...config}=l;return [id,{...config,src:'',artwork:imageForProject(img),knockoutWhite:!!img?.knockoutWhite}]}))}}
async function importProject(data){
 if(data?.format!=='posterr-project'||data.version!==1||!['tv','movie'].includes(data.mode)||typeof data.name!=='string'||data.name.length>300||!data.layers)throw new Error('Choose a valid Posterr project file.');
 const next={};
 for(const [id,defaults] of Object.entries(layers)){
  const saved=data.layers[id];if(!saved||typeof saved.visible!=='boolean')throw new Error('Missing or invalid '+id+' layer.');
  const l={...defaults,img:null,src:''};
  for(const key of Object.keys(defaults)){if(['img','src'].includes(key))continue;const value=saved[key];if(typeof value!==typeof defaults[key])throw new Error('Invalid '+id+' '+key);if(typeof value==='number'&&(!Number.isFinite(value)||Math.abs(value)>1000))throw new Error('Invalid layer dimensions.');if(['color','shadowColor'].includes(key)&&!normalizeHex(value))throw new Error('Invalid layer color.');if(typeof value==='string'&&value.length>300)throw new Error('Invalid layer value.');l[key]=['color','shadowColor'].includes(key)?normalizeHex(value):value}
  if((id==='poster'&&(l.scale<10||l.scale>300))||(['title','service'].includes(id)&&(l.width<1||l.width>100)))throw new Error('Invalid artwork size.');
  if(saved.artwork!==null){if(typeof saved.artwork!=='string'||!/^data:image\/png;base64,/.test(saved.artwork)||saved.artwork.length>50e6)throw new Error('Invalid embedded artwork.');l.img=await loadImage(saved.artwork);l.img.knockoutWhite=!!saved.knockoutWhite;l.src=saved.artwork}
  next[id]=l;
 }
 checkpoint();cancelColorPick();restore({layers:next,mode:data.mode,media:data.media&&typeof data.media==='object'?data.media:null,images:{posters:[],logos:[]},selectedLayer:Object.hasOwn(layers,data.selectedLayer)?data.selectedLayer:'poster',titleLanguage:'all',name:data.name,search:data.name});$('neutralOnly').checked=data.neutralOnly!==false;status('Poster imported. All layers are ready to edit.');
}
$('savePosterBtn').onclick=()=>{try{download(new Blob([JSON.stringify(makeProject())],{type:'application/json'}),($('workspaceName').textContent.replace(/[^a-z0-9_-]+/gi,'-')||'poster')+'.posterr.json');status('Editable poster saved with its artwork and layer settings.')}catch{status('Could not save artwork from this image host. Upload the artwork locally and save again.')}};
$('importPosterBtn').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100e6)throw new Error('Project files must be smaller than 100 MB.');await importProject(JSON.parse(await file.text()))}catch(err){status('Could not import poster: '+err.message)}finally{e.target.value=''}};
